// Construir prompt contextual inteligente
const message = $json.message;
const intent = $json.intent;
const context = $json.context || {};
const kbContext = $json.kbContext;
const personality = $json.personality;

// Construir histórico formatado
let historyText = '';
if (context.conversation && context.conversation.history) {
  const history = context.conversation.history.slice(-8);
  if (history.length > 0) {
    historyText = history
      .map(h => `${h.role === 'assistant' ? 'Assistente' : 'Cliente'}: ${h.content}`)
      .join('\n\n');
  }
}

// Construir contexto de KB
let kbText = '';
if (kbContext && Array.isArray(kbContext) && kbContext.length > 0) {
  kbText = '\n\nInformações relevantes da base de conhecimento:\n' +
    kbContext.map(kb => {
      const body = typeof kb === 'string' ? kb : (kb.body || kb.content || '');
      const title = typeof kb === 'string' ? 'Informação' : (kb.title || 'Artigo');
      return `- ${title}: ${body.substring(0, 200)}${body.length > 200 ? '...' : ''}`;
    }).join('\n');
}

// Personalidades
const personalities = {
  professional: {
    tone: 'profissional e cordial',
    style: 'formal mas amigável',
    emoji: false
  },
  friendly: {
    tone: 'amigável e descontraído',
    style: 'conversacional',
    emoji: true
  },
  technical: {
    tone: 'preciso e técnico',
    style: 'detalhado e objetivo',
    emoji: false
  }
};

const personalityConfig = personalities[personality] || personalities.professional;

// Prompts específicos por intenção
const intentPrompts = {
  'INFO_GERAL': {
    instruction: 'Forneça informações claras, úteis e completas sobre nossos produtos/serviços.',
    focus: 'Seja detalhado mas não verboso. Priorize clareza.'
  },
  'SUPORTE_TECNICO': {
    instruction: 'Ajude o cliente a resolver o problema técnico passo a passo. Seja didático.',
    focus: 'Forneça soluções práticas e acionáveis.'
  },
  'PEDIDO_STATUS': {
    instruction: 'Forneça informações precisas sobre o status do pedido quando disponível.',
    focus: 'Se não tiver informações, seja honesto e ofereça como obter.'
  },
  'RETENÇÃO': {
    instruction: 'Seja extremamente empático. Tente ajudar o cliente, mas respeite sua decisão.',
    focus: 'Demonstre compreensão. Não seja insistente.'
  },
  'ESCALACAO': {
    instruction: 'Informe que está escalando para um agente humano. Seja transparente.',
    focus: 'Tranquilize o cliente que será atendido em breve.'
  },
  'OUTRO': {
    instruction: 'Responda de forma útil e amigável ao melhor de sua capacidade.',
    focus: 'Se não souber algo, seja honesto.'
  }
};

const intentConfig = intentPrompts[intent] || intentPrompts['OUTRO'];

// Informações do cliente
const customerInfo = context.requester ? 
  `\nCliente: ${context.requester.name || 'Cliente'}${context.requester.email ? ` (${context.requester.email})` : ''}` :
  '';

const channelInfo = context.ticket?.channel ? `\nCanal: ${context.ticket.channel}` : '';

// Construir prompt do sistema
const systemPrompt = `Você é um assistente virtual de atendimento ao cliente especializado, ${personalityConfig.tone} e ${personalityConfig.style}.

SUA PERSONALIDADE:
- Seja sempre ${personalityConfig.tone}
- Use linguagem ${personalityConfig.style}
${personalityConfig.emoji ? '- Você pode usar emojis ocasionalmente para humanizar' : '- Não use emojis'}
- Mantenha respostas concisas mas completas
- Se não souber algo, seja honesto e ofereça alternativas
- Mantenha o contexto da conversa anterior
- Demonstre empatia quando apropriado

${intentConfig.instruction}
${intentConfig.focus}

${customerInfo}${channelInfo}

IMPORTANTE:
- Nunca invente informações sobre produtos ou serviços
- Se o problema requer dados que você não tem, seja claro sobre isso
- Mantenha tom positivo e solucionador`;

// Construir prompt do usuário
const userPrompt = `${historyText ? `Histórico da conversa:\n${historyText}\n\n` : ''}${kbText}
Mensagem atual do cliente:
${message}

${intentConfig.instruction}

Responda de forma natural, útil e ${personalityConfig.style}.`;

return {
  json: {
    systemPrompt,
    userPrompt,
    message,
    intent,
    context,
    kbContext,
    personality: personalityConfig
  }
};

// Processar e limpar resposta
const aiResponse = $('IA: Gerar Resposta').item.json.choices[0].message.content;
const context = $('Construir Prompt').item.json;

// Limpar resposta
let cleanedResponse = aiResponse.trim();

// Remover prefixos comuns da IA
const prefixes = ['Assistente:', 'Bot:', 'IA:', 'Resposta:', 'Eu:', 'Sou o assistente virtual'];
for (const prefix of prefixes) {
  const prefixLower = prefix.toLowerCase();
  if (cleanedResponse.toLowerCase().startsWith(prefixLower)) {
    cleanedResponse = cleanedResponse.substring(prefix.length).trim();
  }
}

// Remover sufixos comuns
const suffixes = ['\n\nEspero ter ajudado!', '\n\nPosso ajudar com mais alguma coisa?'];
for (const suffix of suffixes) {
  if (cleanedResponse.endsWith(suffix)) {
    cleanedResponse = cleanedResponse.substring(0, cleanedResponse.length - suffix.length).trim();
  }
}

// Validar comprimento
const maxLength = parseInt($env.OPENAI_MAX_TOKENS) || 2000;
if (cleanedResponse.length > maxLength) {
  cleanedResponse = cleanedResponse.substring(0, maxLength - 3) + '...';
}

return {
  json: {
    response: cleanedResponse,
    rawResponse: aiResponse,
    intent: context.intent,
    context: context.context,
    personality: context.personality,
    generatedAt: new Date().toISOString(),
    metadata: {
      model: $env.OPENAI_MODEL || 'gpt-4',
      length: cleanedResponse.length,
      originalLength: aiResponse.length
    }
  }
};

// Formatar saída final
const processed = $('Processar Resposta').item.json;

const output = {
  success: true,
  response: processed.response,
  intent: processed.intent,
  timestamp: processed.generatedAt,
  metadata: processed.metadata,
  raw: processed
};

return {
  json: output
};
